package com.crm.fees;
import com.crm.fees.service.*;import com.crm.fees.service.impl.FeeServiceImpl;import com.crm.fees.entity.Fee;import com.crm.fees.dto.FeeRequest;import com.crm.fees.mapper.FeeMapper;import com.crm.fees.repository.FeeRepository;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class FeeFinancialPolicyTest {
 final FeeRepository repo=mock(FeeRepository.class);final FeeReferenceDirectory directory=mock(FeeReferenceDirectory.class);final FeeServiceImpl service=new FeeServiceImpl(repo,new FeeMapper(),directory);
 static FeeRequest request(){var r=new FeeRequest();r.setEmployeeId("101");r.setServiceName("Consulting");r.setHourlyRate(new BigDecimal("12.34"));r.setWorkedHours(new BigDecimal("2.50"));return r;}
 @BeforeEach void setup(){when(repo.save(any())).thenAnswer(c->{Fee row=c.getArgument(0);row.setId(1L);return row;});}
 @Test void nominalCalculationAndExactHoursArePersisted(){var r=request();var result=service.createFee(r,"Bearer test");assertEquals(new BigDecimal("30.85"),result.getAmount());assertEquals(new BigDecimal("2.50"),result.getWorkedHours());verify(directory).validate("101",null,"Bearer test");}
 @Test void roundingIsHalfUpNotBinary(){assertEquals(new BigDecimal("0.01"),FeeFinance.amount(new BigDecimal("0.50"),new BigDecimal("0.01")));assertEquals(new BigDecimal("1.01"),FeeFinance.amount(new BigDecimal("1.01"),new BigDecimal("1")));}
 @Test void roundedZeroIsNotRecordedAsACharge(){assertThrows(IllegalArgumentException.class,()->FeeFinance.amount(new BigDecimal("0.01"),new BigDecimal("0.01")));}
 @Test void maximumIsAcceptedAndOverflowRejected(){assertEquals(FeeFinance.MAX,FeeFinance.amount(FeeFinance.MAX,BigDecimal.ONE));assertThrows(IllegalArgumentException.class,()->FeeFinance.amount(FeeFinance.MAX,new BigDecimal("1.01")));}
 @Test void precisionNegativeNullAndHourOverflowAreRejectedBeforeAnyWrite(){for(String value:List.of("-1","0","1.001","10000000000")){var r=request();r.setHourlyRate(new BigDecimal(value));assertThrows(IllegalArgumentException.class,()->service.createFee(r,"Bearer test"));}var r=request();r.setWorkedHours(new BigDecimal("1000000"));assertThrows(IllegalArgumentException.class,()->service.createFee(r,"Bearer test"));r.setWorkedHours(null);assertThrows(IllegalArgumentException.class,()->service.createFee(r,"Bearer test"));verifyNoInteractions(repo,directory);}
 @Test void invalidCurrencyIsRejected(){var r=request();r.setCurrency("tnd");assertThrows(IllegalArgumentException.class,()->service.createFee(r,"Bearer test"));verifyNoInteractions(repo);}
 @Test void invalidCalculatedUpdateDoesNotMutateTheExistingEntity(){var row=new FeeMapper().toEntity(request());row.setId(7L);row.setAmount(new BigDecimal("30.85"));when(repo.lockById(7L)).thenReturn(Optional.of(row));var r=request();r.setHourlyRate(FeeFinance.MAX);assertThrows(IllegalArgumentException.class,()->service.updateFee(7L,r,"Bearer test"));assertEquals(new BigDecimal("12.34"),row.getHourlyRate());}
 @Test void timeDerivedFeesCannotBeEditedOrDeleted(){var row=new FeeMapper().toEntity(request());row.setId(7L);row.setSourceTimeId(9L);when(repo.lockById(7L)).thenReturn(Optional.of(row));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateFee(7L,request(),"Bearer test"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.deleteFee(7L));verify(repo,never()).delete(any(Fee.class));}
 @Test void historicalBilledPaidOrUnknownStatusIsProtected(){var row=new FeeMapper().toEntity(request());row.setId(7L);when(repo.lockById(7L)).thenReturn(Optional.of(row));for(String status:List.of("INVOICED","PAID","unqualified old state")){row.setInvoiceStatus(status);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.deleteFee(7L));}}
 @Test void pendingHistoricalReferencesAreRetainedWithoutRevalidation(){var r=request();r.setEmployeeId("OLD-CODE");var row=new FeeMapper().toEntity(r);row.setId(7L);row.setInvoiceStatus("PENDING");when(repo.lockById(7L)).thenReturn(Optional.of(row));service.updateFee(7L,r,"Bearer test");verifyNoInteractions(directory);}
 @Test void changedReferencesAreCheckedBeforeMutation(){var row=new FeeMapper().toEntity(request());row.setId(7L);when(repo.lockById(7L)).thenReturn(Optional.of(row));var r=request();r.setCustomerId("202");doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND)).when(directory).validate(any(),any(),any());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateFee(7L,r,"Bearer test"));assertNull(row.getCustomerId());}
 @Test void historicalDoubleIsReadWithoutRewritingStoredAmount(){var row=new Fee();row.setWorkedHours(1.23456);row.setAmount(new BigDecimal("123.45"));var mapped=new FeeMapper().toResponse(row);assertEquals(new BigDecimal("1.23456"),mapped.getWorkedHours());assertEquals(new BigDecimal("123.45"),mapped.getAmount());assertNull(row.getExactHours());}
}